package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DatabindContext;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ClassNameIdResolver__typeFromId_TriageGen0Test {

    private TypeFactory typeFactory;
    private JavaType baseType;
    private ClassNameIdResolver resolver;
    private DeserializationContext deserializationContext;

    @Before
    public void setUp() {
        typeFactory = mock(TypeFactory.class);
        baseType = mock(JavaType.class);
        deserializationContext = mock(DeserializationContext.class);
        // We use a subclass to access the protected method _typeFromId
        resolver = new ClassNameIdResolver(baseType, typeFactory) {
            @Override
            public JavaType _typeFromId(String id, DatabindContext ctxt) throws IOException {
                return super._typeFromId(id, ctxt);
            }
        };
    }

    @Test
    public void testTypeFromId_WithGenerics() throws IOException {
        String id = "java.util.List<java.lang.String>";
        JavaType expectedType = mock(JavaType.class);

        when(deserializationContext.getTypeFactory()).thenReturn(typeFactory);
        when(typeFactory.constructFromCanonical(id)).thenReturn(expectedType);

        JavaType result = resolver._typeFromId(id, deserializationContext);

        assertEquals(expectedType, result);
    }

    @Test
    public void testTypeFromId_SimpleClassSuccess() throws IOException {
        String id = "java.lang.String";
        Class<String> cls = String.class;
        JavaType expectedType = mock(JavaType.class);

        when(deserializationContext.getTypeFactory()).thenReturn(typeFactory);
        when(typeFactory.findClass(id)).thenReturn(cls);
        when(typeFactory.constructSpecializedType(baseType, cls)).thenReturn(expectedType);

        JavaType result = resolver._typeFromId(id, deserializationContext);

        assertEquals(expectedType, result);
    }

    @Test
    public void testTypeFromId_ClassNotFound_HandledByDeserializationContext() throws IOException {
        String id = "com.nonexistent.Class";
        JavaType expectedType = mock(JavaType.class);

        when(deserializationContext.getTypeFactory()).thenReturn(typeFactory);
        when(typeFactory.findClass(id)).thenThrow(new ClassNotFoundException("Not found"));
        when(deserializationContext.handleUnknownTypeId(eq(baseType), eq(id), eq(resolver), any(String.class)))
                .thenReturn(expectedType);

        JavaType result = resolver._typeFromId(id, deserializationContext);

        assertEquals(expectedType, result);
    }

    @Test
    public void testTypeFromId_ClassNotFound_NotDeserializationContext() throws IOException {
        String id = "com.nonexistent.Class";
        DatabindContext plainContext = mock(DatabindContext.class);

        when(plainContext.getTypeFactory()).thenReturn(typeFactory);
        when(typeFactory.findClass(id)).thenThrow(new ClassNotFoundException("Not found"));

        JavaType result = resolver._typeFromId(id, plainContext);

        assertNull(result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testTypeFromId_ExceptionThrowsIllegalArgumentException() throws IOException {
        String id = "invalid.id";

        when(deserializationContext.getTypeFactory()).thenReturn(typeFactory);
        // Simulating a generic Exception that is not ClassNotFoundException
        when(typeFactory.findClass(id)).thenThrow(new RuntimeException("Unexpected error"));

        resolver._typeFromId(id, deserializationContext);
    }

    @Test
    public void testTypeFromId_GenericsEdgeCase_IndexZero() throws IOException {
        // id.indexOf('<') > 0 check. If '<' is at index 0, it goes to findClass path.
        String id = "<java.lang.String>"; 
        Class<String> cls = String.class;
        JavaType expectedType = mock(JavaType.class);

        when(deserializationContext.getTypeFactory()).thenReturn(typeFactory);
        when(typeFactory.findClass(id)).thenReturn(cls);
        when(typeFactory.constructSpecializedType(baseType, cls)).thenReturn(expectedType);

        JavaType result = resolver._typeFromId(id, deserializationContext);

        assertEquals(expectedType, result);
    }
}
